solution.solution.rs:
fn add_score(scores: &mut Vec<u32>, score: u32) -> usize {
    scores.push(score);
    scores.len()
}

fn best<'a>(scores: &'a Vec<u32>) -> Option<&'a u32> {
    if scores.is_empty() {
        return None;
    }
    let mut top = &scores[0];
    for s in scores {
        if *s > *top {
            top = s;
        }
    }
    Some(top)
}

fn normalize(words: &mut Vec<String>) {
    for w in words.iter_mut() {
        *w = w.trim().to_lowercase();
    }
}

fn swap_ends(values: &mut Vec<i32>) {
    let n = values.len();
    if n >= 2 {
        let first = values[0];
        values[0] = values[n - 1];
        values[n - 1] = first;
    }
}

fn count_starting(words: &Vec<String>, prefix: &str) -> usize {
    let p = prefix.to_lowercase();
    let mut count = 0;
    for w in words {
        if w.to_lowercase().starts_with(&p) {
            count += 1;
        }
    }
    count
}

unitTests:
test("adding scores", || {
    let mut scores = vec![10];
    check_eq(add_score(&mut scores, 7), 2);
    check_eq(add_score(&mut scores, 12), 3);
    check_eq(scores, vec![10, 7, 12]);
});

test("the best score", || {
    let scores = vec![4, 9, 2, 9];
    let top = best(&scores);
    check_eq(top, Some(&9));
    check(std::ptr::eq(top.unwrap(), &scores[1]));
    check_eq(best(&Vec::new()), None);
});

test("normalizing in place", || {
    let mut words = vec!["  Tea ".to_string(), "CAKE".to_string(), "".to_string()];
    normalize(&mut words);
    check_eq(words, vec!["tea", "cake", ""]);
});

test("swapping ends", || {
    let mut v = vec![1, 2, 3, 4];
    swap_ends(&mut v);
    check_eq(v, vec![4, 2, 3, 1]);
    let mut two = vec![5, 6];
    swap_ends(&mut two);
    check_eq(two, vec![6, 5]);
    let mut one = vec![7];
    swap_ends(&mut one);
    check_eq(one, vec![7]);
    let mut empty: Vec<i32> = Vec::new();
    swap_ends(&mut empty);
    check_eq(empty.len(), 0);
});

test("counting by prefix", || {
    let words: Vec<String> = ["Apple", "apricot", "banana", "APEX"].iter().map(|s| s.to_string()).collect();
    check_eq(count_starting(&words, "ap"), 3);
    check_eq(count_starting(&words, "Ban"), 1);
    check_eq(count_starting(&words, "z"), 0);
});

